CREATE TABLE IF NOT EXISTS gis_admin_name_aliases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_name text NOT NULL, target_name text NOT NULL, country_code text NOT NULL DEFAULT 'NG', rationale text NOT NULL, source_authority text NOT NULL DEFAULT 'GIS evidence review', status text NOT NULL DEFAULT 'Proposed', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(country_code,source_name,target_name));